1265	
1266	/**
1267	 * B：在售清单 diff 点名。
1268	 * - 下架：上轮在售、本轮不在 → 立即点名（productId 冷却）
1269	 * - 上架：新进先 pending，**连续两轮仍在售** 再点名（与赛狐二次确认同思路）
1270	 * - 允许 tabCount===0 的真实空列表（整店下架）
1271	 * - items 空且 tabCount 未知/失败 → 不动基准
1272	 */
1273	async function diffOnSale(name, items, onSaleTabCount, scanStore) {
1274	  if (!ONSALE_MONITOR_IN_PLUGIN || !ONSALE_SCAN_ALERT) return { delisted: 0, listed: 0 };
1275	  if (scanStore && scanStore !== name) {
1276	    log.warn('onSale scan store mismatch: want=' + name + ' got=' + scanStore + '，本轮作废');
1277	    return { delisted: 0, listed: 0, aborted: true };
1278	  }
1279	  if (!Array.isArray(items)) {
1280	    log.warn('onSale scan invalid items: store=' + name);
1281	    return { delisted: 0, listed: 0, aborted: true };
1282	  }
1283	
1284	  const cfg = await getConfig();
1285	  const now = Date.now();
1286	  const trueZero = typeof onSaleTabCount === 'number' && onSaleTabCount === 0 && items.length === 0;
1287	  if (!items.length && !trueZero) {
1288	    // 空且不是权威 0 → 扫描失败，不动基准
1289	    log.warn('onSale scan empty (not authoritative zero): store=' + name + ' tabCount=' + onSaleTabCount);
1290	    return { delisted: 0, listed: 0, aborted: true };
1291	  }
1292	
1293	  // 防残缺/污染：以干净视图「在售中 N」为权威
1294	  const known = (typeof onSaleTabCount === 'number' && onSaleTabCount >= 0)
1295	    ? onSaleTabCount
1296	    : null;
1297	  if (known != null && known > 0 && items.length < known) {
1298	    log.warn('onSale scan incomplete: store=' + name + ' scanned=' + items.length + ' known=' + known);
1299	    return { delisted: 0, listed: 0, aborted: true };
1300	  }
1301	  if (known != null && items.length > known) {
1302	    log.warn('onSale scan overflow: store=' + name + ' scanned=' + items.length + ' known=' + known + '，疑似视图污染，本轮作废');
1303	    return { delisted: 0, listed: 0, aborted: true };
1304	  }
1305	
1306	  const newMap = {};
1307	  for (const it of items) {
1308	    if (it && it.productId) {
1309	      newMap[String(it.productId)] = {
1310	        name: it.name || '',
1311	        skc: it.skc || '',
1312	        productId: String(it.productId),
1313	      };
1314	    }
1315	  }
1316	
1317	  let g = await getOnSaleAlertedGlobal();
1318	  g.delist = pruneTsMap(g.delist, now, ONSALE_ID_COOLDOWN_MS);
1319	  g.onshelf = pruneTsMap(g.onshelf, now, ONSALE_ID_COOLDOWN_MS);
1320	
1321	  const pack = await withStores(async () => {
1322	    const stores = await getStores();
1323	    const s = stores[name] || { latest: {}, snapshot: {} };
1324	    const snap = s.snapshot || {};
1325	    const prevMap = snap.onSaleIds && typeof snap.onSaleIds === 'object' ? snap.onSaleIds : null;
1326	    const prevPending = snap.pendingOnshelf && typeof snap.pendingOnshelf === 'object' ? snap.pendingOnshelf : {};
1327	
1328	    if (!prevMap) {
1329	      // 首轮：建确认基准，不告警；当前列表全部视为已确认在售（不进 pending）
1330	      s.snapshot = Object.assign({}, snap, {
