1	/**
2	 * v19 A+B 在售 diff 纯逻辑自测（不启动 Chrome）
3	 * node test_onsale_ab.js
4	 */
5	function assert(cond, msg) {
6	  if (!cond) throw new Error(msg || 'assert failed');
