8	
9	// —— 复制 background 中的核心判定（保持与实现一致）——
10	function computeDiff(prevMap, prevPending, items, onSaleTabCount) {
11	  const trueZero = typeof onSaleTabCount === 'number' && onSaleTabCount === 0 && items.length === 0;
12	  if (!Array.isArray(items)) return { aborted: true };
13	  if (!items.length && !trueZero) return { aborted: true, reason: 'empty' };
14	
15	  const known = typeof onSaleTabCount === 'number' && onSaleTabCount >= 0 ? onSaleTabCount : null;
16	  if (known != null && known > 0 && items.length < known) return { aborted: true, reason: 'incomplete' };
17	  if (known != null && items.length > known) return { aborted: true, reason: 'overflow' };
18	
19	  const newMap = {};
20	  for (const it of items) {
21	    if (it && it.productId) newMap[String(it.productId)] = { name: it.name || '', skc: it.skc || '', productId: String(it.productId) };
22	  }
23	
24	  if (!prevMap) {
25	    return { first: true, onSaleIds: newMap, pending: {}, delisted: [], listed: [] };
26	  }
27	
28	  const rawDelisted = Object.keys(prevMap).filter((pid) => !(pid in newMap));
29	  const confirmedListed = [];
30	  for (const pid of Object.keys(prevPending || {})) {
31	    if (pid in newMap) confirmedListed.push(pid);
32	  }
33	  const listedSet = new Set(confirmedListed);
34	  const nextPending = {};
35	  for (const pid of Object.keys(newMap)) {
36	    if (pid in prevMap) continue;
37	    if (listedSet.has(pid)) continue;
38	    nextPending[pid] = { productId: pid, name: newMap[pid].name, skc: newMap[pid].skc };
39	  }
40	  const nextOnSale = {};
41	  for (const pid of Object.keys(prevMap)) {
42	    if (pid in newMap) nextOnSale[pid] = newMap[pid];
43	  }
44	  for (const pid of confirmedListed) nextOnSale[pid] = newMap[pid];
45	
46	  return {
47	    first: false,
48	    delisted: rawDelisted,
49	    listed: confirmedListed,
50	    pending: nextPending,
51	    onSaleIds: nextOnSale,
52	  };
53	}
54	
55	// 1) 首轮建基
56	{
57	  const r = computeDiff(null, {}, [{ productId: 'A', name: 'a' }], 1);
58	  assert(r.first && r.onSaleIds.A, 'first baseline');
59	}
60	
61	// 2) 下架点名
62	{
63	  const prev = { A: { name: '茶蜡', skc: '1' }, B: { name: 'x', skc: '2' } };
64	  const r = computeDiff(prev, {}, [{ productId: 'B', name: 'x' }], 1);
65	  assert(!r.first && r.delisted.length === 1 && r.delisted[0] === 'A', 'delist A');
66	  assert(!r.pending.A && r.onSaleIds.B, 'B remains');
67	}
68	
69	// 3) 真清零
70	{
71	  const prev = { A: { name: '茶蜡', skc: '7636599333' } };
72	  const r = computeDiff(prev, {}, [], 0);
73	  assert(r.delisted.length === 1 && r.delisted[0] === 'A', 'true zero delist');
74	  assert(Object.keys(r.onSaleIds).length === 0, 'empty baseline after zero');
