81	  assert(r.aborted, 'empty abort');
82	}
83	
84	// 5) 上架二次确认
85	{
86	  const prev = { A: { name: 'a' } };
87	  const r1 = computeDiff(prev, {}, [{ productId: 'A', name: 'a' }, { productId: 'C', name: 'new' }], 2);
88	  assert(r1.listed.length === 0 && r1.pending.C, 'C pending first seen');
89	  assert(!r1.onSaleIds.C, 'C not in committed yet');
90	  const r2 = computeDiff(r1.onSaleIds, r1.pending, [{ productId: 'A', name: 'a' }, { productId: 'C', name: 'new' }], 2);
91	  assert(r2.listed.length === 1 && r2.listed[0] === 'C', 'C confirmed second round');
92	  assert(r2.onSaleIds.C, 'C in baseline');
93	  assert(!r2.pending.C, 'C left pending');
94	}
