111	// 8) 数量 A 逻辑（旧：立即判定）
112	function qtyDecision(prev, cur) {
113	  if (prev == null) return { first: true, shouldScan: false };
114	  if (prev === cur) return { dropped: 0, rose: 0, shouldScan: false };
115	  const dropped = cur < prev ? prev - cur : 0;
116	  const rose = cur > prev ? cur - prev : 0;
117	  return { dropped, rose, shouldScan: dropped > 0 || rose > 0, from: prev, to: cur };
118	}
119	assert(qtyDecision(null, 13).first, 'qty first');
120	assert(qtyDecision(1, 0).dropped === 1 && qtyDecision(1, 0).shouldScan, '1→0');
121	assert(qtyDecision(13, 14).rose === 1, 'rise');
