124	// 9) v19.2 数量防抖：纯状态机（与 background.diffOnSaleCount 对齐）
125	const QTY_HITS = 2;
126	const QTY_GAP_MS = 3000;
127	const QTY_TTL_MS = 60 * 1000;
128	
129	function qtyConfirmStep(state, cur, now) {
130	  // state: { base, pending: null|{from,to,firstTs,hits} }
131	  let { base, pending } = state;
132	  if (pending && pending.firstTs && now - pending.firstTs > QTY_TTL_MS) pending = null;
133	
134	  if (base == null) {
135	    return {
136	      state: { base: cur, pending: null },
137	      alert: false,
138	      shouldScan: false,
139	      confirmed: false,
140	      first: true,
141	    };
142	  }
143	  if (cur === base) {
144	    return {
145	      state: { base, pending: null },
146	      alert: false,
147	      shouldScan: false,
148	      confirmed: false,
149	      cancelled: !!pending,
150	    };
151	  }
152	
153	  let nextPending;
154	  if (pending && pending.to === cur) {
155	    nextPending = {
156	      from: base,
157	      to: cur,
158	      firstTs: pending.firstTs,
159	      hits: (pending.hits || 1) + 1,
