    alerted = markAlerted(alerted, pool, now);
    globalAlerted = markAlerted(globalAlerted, pool, now);
    seeded = true;
    log.info('Traffic baseline seeded: store=' + name + ' known=' + Object.keys(alerted).length
      + ' pool=' + pool.length);
