$ErrorActionPreference = 'Stop'
Add-Type -AssemblyName System.IO.Compression
Add-Type -AssemblyName System.IO.Compression.FileSystem
$src = 'E:\project\temu\temu-plugin'
$outPath = 'E:\project\temu\temu-plugin-v19.4-防假清零+限流基线.zip'
$files = @(
  'manifest.json','background.js','content.js','content-front.js','inject.js',
  'logger.js','feishuApp.js','popup.html','popup.js','options.html','options.js',
  '使用说明.txt'
)
foreach ($f in $files) {
  if (-not (Test-Path -LiteralPath (Join-Path $src $f))) { throw "missing: $f" }
}
$mf = Get-Content (Join-Path $src 'manifest.json') -Raw -Encoding UTF8
if ($mf -notmatch '"version"\s*:\s*"0\.2\.9"') { throw 'manifest not 0.2.9' }
$bg = Get-Content (Join-Path $src 'background.js') -Raw -Encoding UTF8
if ($bg -notmatch "bgVersion:\s*'v19\.4") { throw 'bgVersion not v19.4' }
$ctHead = (Get-Content (Join-Path $src 'content.js') -TotalCount 10 -Encoding UTF8) -join "`n"
if ($ctHead -notmatch 'v19\.4') { throw 'content.js not v19.4' }

if (Test-Path -LiteralPath $outPath) {
  [IO.File]::Delete($outPath)
}
$fs = [IO.File]::Open($outPath, [IO.FileMode]::CreateNew)
try {
  $zip = New-Object IO.Compression.ZipArchive($fs, [IO.Compression.ZipArchiveMode]::Create)
  try {
    foreach ($f in $files) {
      $entry = $zip.CreateEntry($f, [IO.Compression.CompressionLevel]::Optimal)
      $entryStream = $entry.Open()
      try {
        $bytes = [IO.File]::ReadAllBytes((Join-Path $src $f))
        $entryStream.Write($bytes, 0, $bytes.Length)
      } finally { $entryStream.Dispose() }
    }
  } finally { $zip.Dispose() }
} finally { $fs.Dispose() }

$item = Get-Item -LiteralPath $outPath
Write-Host "OK  $($item.FullName)"
Write-Host ("size = {0:N1} KB" -f ($item.Length/1KB))
$z = [IO.Compression.ZipFile]::OpenRead($outPath)
try { $z.Entries | ForEach-Object { Write-Host ("  {0}  ({1} bytes)" -f $_.FullName, $_.Length) } } finally { $z.Dispose() }
